// Acceso al campo 'subject' del nodo IMAP anterior
const subject = items[0].json.subject; 

if (!subject) {
    throw new Error("El asunto del correo está vacío.");
}

// Regex estricto para capturar el patrón YYYY-MM-DD/YYYY-MM-DD
const datePattern = /(\d{4}-\d{2}-\d{2})\/(\d{4}-\d{2}-\d{2})/;
const match = subject.match(datePattern);

if (match) {
    return {
        FechaInicio: match[1],
        FechaFin: match[2]
    };
} else {
    // Si el asunto no cumple el formato, el nodo fallará indicando el motivo
    throw new Error("Formato de fechas no encontrado en el asunto: " + subject);
}
